const b = $json.body || {};
const KNOWN = ['facebook', 'instagram', 'whatsapp', 'linkedin'];
const errors = [];

if (!b.business_name || String(b.business_name).trim().length < 2) errors.push('business_name is required');
if (!b.brief || String(b.brief).trim().length < 15) errors.push('brief must be at least 15 characters');

const platforms = Array.isArray(b.platforms)
  ? [...new Set(b.platforms.map(p => String(p).toLowerCase()))].filter(p => KNOWN.includes(p))
  : [];
if (platforms.length === 0) errors.push('select at least one supported platform');

return {
  json: {
    valid: errors.length === 0,
    errors,
    input: {
      business_name: String(b.business_name || '').trim(),
      sector: String(b.sector || 'general').trim(),
      product: String(b.product || '').trim(),
      audience: String(b.audience || 'general audience').trim(),
      tone: String(b.tone || 'warm, informative').trim(),
      objective: String(b.objective || 'brand_awareness').trim(),
      brief: String(b.brief || '').trim().slice(0, 3000),
      platforms
    }
  }
};

const input = $('Code - Validate Brief').first().json.input;
const raw = $input.first().json || {};
const allowed = new Set(input.platforms);

let text = '';
for (const c of (raw.candidates || [])) {
  for (const p of ((c.content || {}).parts || [])) {
    if (typeof p.text === 'string' && p.text.trim()) { text = p.text; break; }
  }
  if (text) break;
}

let out = null;
try { out = JSON.parse(String(text).replace(/^```(?:json)?/i, '').replace(/```$/, '').trim()); } catch (e) { out = null; }

if (!out) {
  return [{ json: { success: false, status: 'generation_failed', message: (raw.error && raw.error.message) || 'Gemini did not return usable JSON. Check GEMINI_MODEL and the API key.', posts: [] } }];
}

// Platform authority stays with the request, never with the model.
const posts = (Array.isArray(out.posts) ? out.posts : [])
  .map(p => ({
    platform: String(p.platform || '').toLowerCase(),
    headline: String(p.headline || '').trim(),
    caption: String(p.caption || '').trim(),
    hashtags: Array.isArray(p.hashtags) ? p.hashtags.filter(h => typeof h === 'string' && h.startsWith('#')) : [],
    cta: String(p.cta || '').trim(),
    alt_text: String(p.alt_text || '').trim(),
    best_time_to_post: String(p.best_time_to_post || '').trim()
  }))
  .filter(p => allowed.has(p.platform) && p.caption)
  .map(p => ({ ...p, hashtags: p.platform === 'whatsapp' ? [] : p.hashtags.slice(0, 12), character_count: p.caption.length }));

return [{
  json: {
    success: posts.length > 0,
    status: posts.length > 0 ? 'generated' : 'generation_failed',
    source: 'n8n',
    campaign_id: 'n8n-' + Date.now().toString(36),
    generated_at: new Date().toISOString(),
    content_model: $env.GEMINI_MODEL || 'gemini-3.6-flash',
    business_name: input.business_name,
    requested_platforms: input.platforms,
    missing_platforms: input.platforms.filter(p => !posts.some(x => x.platform === p)),
    campaign: out.campaign || {},
    posts,
    image_prompt: String(out.image_prompt || '').trim(),
    image_alt_text: String(out.image_alt_text || '').trim(),
    message: posts.length > 0 ? 'Campaign generated' : 'No usable posts were produced'
  }
}];

const ctx = $('Code - Parse Content').first().json;
const raw = $input.first().json || {};

let data = null, mime = null;
for (const c of (raw.candidates || [])) {
  for (const p of ((c.content || {}).parts || [])) {
    const inline = p.inlineData || p.inline_data;
    if (inline && inline.data) { data = inline.data; mime = inline.mimeType || inline.mime_type || 'image/png'; break; }
  }
  if (data) break;
}

// The image is returned as a data URI so no object storage is required for the demo.
return [{
  json: {
    ...ctx,
    image: data
      ? { available: true, url: 'data:' + mime + ';base64,' + data, mime_type: mime, model: $env.GEMINI_IMAGE_MODEL || 'gemini-2.5-flash-image' }
      : { available: false, reason: (raw.error && raw.error.message) ? 'provider_error' : 'no_image_returned', detail: (raw.error && raw.error.message) || null }
  }
}];
